CREATE OR REPLACE FUNCTION public.fn_get_experience_schedule_by_id(p_tenant_id uuid, p_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, experience_id uuid, classroom_id uuid, scheduled_date date, time_of_day character varying, status character varying, primary_teacher_id uuid, planned_start_time time without time zone, planned_end_time time without time zone, preparation_notes text, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT es.id, es.tenant_id, es.experience_id, es.classroom_id,            es.scheduled_date, es.time_of_day, es.status,            es.primary_teacher_id, es.planned_start_time,            es.planned_end_time, es.preparation_notes,            es.created_at, es.updated_at     FROM experience_schedules es     WHERE es.id = p_id AND es.tenant_id = p_tenant_id; END; $function$ ;
